const DATE_RECOVERY_SHEET = 'Rescate_Fechas';
const LOG_SHEET_NAME_TARGET = 'Registros'; 

function oneShotRecoverDates() {
  const ss = SpreadsheetApp.openById(LOG_SPREADSHEET_ID);
  let targetSheet = ss.getSheetByName(LOG_SHEET_NAME_TARGET);
  let rescueSheet = ss.getSheetByName(DATE_RECOVERY_SHEET);

  if (!targetSheet) throw new Error("No encuentro la hoja 'Registros'.");

  // 1. Preparar Hoja de Rescate
  if (!rescueSheet) {
    rescueSheet = ss.insertSheet(DATE_RECOVERY_SHEET);
    rescueSheet.appendRow(["ID Tarea", "Fecha Original (Log)", "FECHA REAL (Recuperada)", "Fuente"]);
    rescueSheet.setFrozenRows(1);
  }

  // 2. Leer IDs únicos de la hoja Registros para no llamar a la API 10 veces por la misma tarea
  // Asumimos: Columna A = Fecha Log, Columna C = ID Tarea (Índices 0 y 2)
  const data = targetSheet.getDataRange().getValues();
  const uniqueIds = new Map(); // Map<TaskId, {rowIndex, originalDate}>

  console.log(`Analizando ${data.length} filas...`);

  // Empezamos en fila 1 (saltando header)
  for (let i = 1; i < data.length; i++) {
    const taskId = data[i][2]; // Columna C
    const logDate = data[i][0]; // Columna A

    if (taskId && !uniqueIds.has(taskId)) {
      uniqueIds.set(taskId, logDate);
    }
  }

  console.log(`Se encontraron ${uniqueIds.size} tareas únicas para consultar.`);

  // 3. Consultar API y guardar en Rescate
  const tasksArray = Array.from(uniqueIds.entries()); // [[id, date], [id, date]...]

  // Procesamos en lotes para ir guardando
  let buffer = [];

  for (let i = 0; i < tasksArray.length; i++) {
    const [taskId, originalDate] = tasksArray[i];

    try {
      Utilities.sleep(150); // Rate Limiting (Corteseía con la API)

      const taskData = getFieldbeatTaskData_Safe(taskId);
      if (!taskData || !taskData.task) {
        buffer.push([taskId, originalDate, "Error API", "API Fail"]);
        continue;
      }

      const t = taskData.task;

      // === LÓGICA DE EXTRACCIÓN===
      const realDateObj = extractRealDateFromReport(t, originalDate);
      const formattedDate = formatDateForSheet(realDateObj); 
      const source = realDateObj.source;

      buffer.push([taskId, originalDate, formattedDate, source]);
      console.log(`[${i+1}/${tasksArray.length}] ID ${taskId}: ${formattedDate} (${source})`);

    } catch (e) {
      console.error(`Error ID ${taskId}: ${e.message}`);
      buffer.push([taskId, originalDate, "ERROR", e.message]);
    }

    // Guardar cada 20 registros para no perder todo si falla
    if (buffer.length >= 20) {
      rescueSheet.getRange(rescueSheet.getLastRow() + 1, 1, buffer.length, 4).setValues(buffer);
      SpreadsheetApp.flush(); // Forzar escritura
      buffer = [];
    }
  }

  // Guardar remanentes
  if (buffer.length > 0) {
    rescueSheet.getRange(rescueSheet.getLastRow() + 1, 1, buffer.length, 4).setValues(buffer);
  }

  console.log("=== EXTRACCIÓN COMPLETADA ===");
}

