/**
 * Lógica de extracción con Fallback Inteligente
 * 1. Reporte (Campo Explícito)
 * 2. Sistema (Completed_at)
 * 3. Fallback: Fecha del Correo (Log Original)
 */
function extractRealDateFromReport(task, emailDate) {
  const reportGroups = task.report?.groups || [];
  const TARGET_FIELDS = [
    "HORA DE TERMINO DEL TRABAJO", 
    "FECHA Y HORA DE ENTREGA", 
    "FECHA FIN",
    "HORA DE SALIDA" 
  ];

  // 1. Prioridad: Buscar en el Reporte (Dato Humano)
  for (const group of reportGroups) {
    if (!group.fields) continue;
    for (const field of group.fields) {
      if (field.name && TARGET_FIELDS.includes(field.name.toUpperCase().trim()) && field.value) {
        // Usamos el parseador seguro con zona horaria Chile
        return { 
          date: parseCustomDate_Safe(field.value.toString()), 
          source: "REPORTE (Real)" 
        };
      }
    }
  }

  // 2. Prioridad: Fecha de Cierre del Sistema
  if (task.completed_at) {
    return { date: new Date(task.completed_at), source: "SISTEMA (Cierre)" };
  }

  // 3. Fallback Final: Fecha del Correo (Log)
  // Si emailDate es válido lo usamos, si no, usamos hoy (último recurso)
  const finalFallback = emailDate instanceof Date ? emailDate : new Date();

  return { 
    date: finalFallback, 
    source: "FALLBACK (Email)" // Etiqueta clara para auditoría
  };
}

function parseCustomDate_Safe(dateStr) {
  // Parsea "08/01/2026 17:00" -> Date Obj
  try {
    const [fecha, hora] = dateStr.trim().split(' '); 
    const [dia, mes, anio] = fecha.split('/');
    let h = 0, m = 0;
    if (hora) { [h, m] = hora.split(':'); }
    return new Date(parseInt(anio), parseInt(mes) - 1, parseInt(dia), parseInt(h), parseInt(m), 0);
  } catch (e) {
    return new Date();
  }
}

function formatDateForSheet(dateObj) {
  if (!dateObj || !dateObj.date) return "";
  return dateObj.date; // Devolvemos objeto Date, Sheets lo formatea
}

