function mergeRecoveredDates() {
  const ss = SpreadsheetApp.openById(LOG_SPREADSHEET_ID);;
  const sourceSheet = ss.getSheetByName('Rescate_Fechas');
  const targetSheet = ss.getSheetByName('Registros');

  if (!sourceSheet || !targetSheet) throw new Error("Faltan hojas.");

  // 1. Cargar Mapa de Fechas Nuevas
  // Col A=ID (idx 0), Col C=Fecha Real (idx 2) en la hoja de rescate
  const sourceData = sourceSheet.getDataRange().getValues();
  const dateMap = new Map();

  for (let i = 1; i < sourceData.length; i++) {
    const id = sourceData[i][0]; 
    const realDate = sourceData[i][2];
    if (id && realDate instanceof Date) { // Solo si es una fecha válida
      dateMap.set(id.toString().trim(), realDate);
    }
  }

  console.log(`Mapa cargado: ${dateMap.size} fechas corregidas.`);

  // 2. Leer Registros para actualizar
  const lastRow = targetSheet.getLastRow();
  // Leemos IDs (Col C -> índice 3, array idx 0)
  const targetIds = targetSheet.getRange(2, 3, lastRow - 1, 1).getValues();

  // Array para la Columna A (Fechas)
  const outputDates = [];
  const currentDates = targetSheet.getRange(2, 1, lastRow - 1, 1).getValues(); // Leemos las actuales por si acaso

  let updates = 0;

  for (let i = 0; i < targetIds.length; i++) {
    const id = targetIds[i][0].toString().trim();

    if (dateMap.has(id)) {
      outputDates.push([dateMap.get(id)]); // Usamos la nueva fecha
      updates++;
    } else {
      outputDates.push([currentDates[i][0]]); // Mantenemos la vieja si no encontramos dato
    }
  }

  // 3. Sobrescribir Columna A
  targetSheet.getRange(2, 1, outputDates.length, 1).setValues(outputDates);

  console.log(`=== ACTUALIZACIÓN COMPLETA: ${updates} fechas corregidas ===`);
}

