/**
 * Servicio API: Obtiene el JSON crudo sin procesar.
 */
function fetchRawFieldbeatTask(id) {
  const props = PropertiesService.getScriptProperties();
  const user = props.getProperty('FIELDBEAT_API_USER');
  const pass = props.getProperty('FIELDBEAT_API_PASS');
  const url = `https://api.fieldbeat.com/fleets/eyg/tasks/${id}`;

  if (!user || !pass) throw new Error("Credenciales no configuradas.");

  const options = {
    method: 'get',
    headers: { 
      'Authorization': `Basic ${Utilities.base64Encode(`${user}:${pass}`)}` 
    },
    muteHttpExceptions: true
  };

  const response = UrlFetchApp.fetch(url, options);

  if (response.getResponseCode() !== 200) {
    throw new Error(`API Error ${response.getResponseCode()}: ${response.getContentText()}`);
  }

  return JSON.parse(response.getContentText());
}

/**
 * Motor Recursivo: Convierte un objeto anidado en filas de tabla.
 * Genera paths estilo: "task.report.groups[0].fields[2].value"
 */
function flattenObjectForSheet(obj, prefix = '', result = []) {
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      const value = obj[key];
      const newKey = prefix ? `${prefix}.${key}` : key;

      if (value !== null && typeof value === 'object') {
        // Si es array, usamos notación de índice [i]
        if (Array.isArray(value)) {
          if (value.length === 0) {
            result.push([`${newKey} (Array)`, '[VACÍO]', 'Array']);
          } else {
            value.forEach((item, index) => {
              flattenObjectForSheet(item, `${newKey}[${index}]`, result);
            });
          }
        } else {
          // Si es objeto, recursión profunda
          flattenObjectForSheet(value, newKey, result);
        }
      } else {
        // Nodo hoja (Valor final)
        result.push([newKey, value, typeof value]);
      }
    }
  }
  return result;
}

/**
 * Escribe los datos en la hoja de Google Sheets.
 */
function writeToDebugSheet(taskId, data) {
  const ss = SpreadsheetApp.openById(LOG_SPREADSHEET_ID); // Usa tu constante global ID
  let sheet = ss.getSheetByName(DEBUG_SHEET_NAME);

  // Si no existe la hoja, la crea
  if (!sheet) {
    sheet = ss.insertSheet(DEBUG_SHEET_NAME);
  }

  sheet.clear(); // Limpia rastros anteriores

  // Encabezados
  const headers = [['JSON Path (Estructura)', 'Valor Real', 'Tipo de Dato']];
  const timestamp = [['TIMESTAMP EJECUCIÓN', new Date(), `Tarea ID: ${taskId}`]];

  // Formateo visual
  sheet.getRange(1, 1, 1, 3).setValues(headers).setFontWeight('bold').setBackground('#E0E0E0');
  sheet.getRange(2, 1, 1, 3).setValues(timestamp).setFontStyle('italic');

  // Volcado masivo
  if (data.length > 0) {
    sheet.getRange(4, 1, data.length, 3).setValues(data);
  }

  // Ajuste de ancho de columnas para legibilidad
  sheet.setColumnWidth(1, 400); // Path ancho
  sheet.setColumnWidth(2, 300); // Valor
  sheet.setColumnWidth(3, 100); // Tipo
}
